import React, { useState, useEffect } from 'react';
import AppRouter from "./AppRouter";
import Footer from "./components/Footer/Footer";
import Header from "./components/Header/Header";
import ScrollToTop from "./ScrollToTop";
import ModalContact from './components/ModalWindow/ModalContact';
import ModalOverlay from './components/ModalWindow/ModalOverlay';
import classes from './App.module.scss'; // Import App.module.scss

function App() {
  const [showContactModal, setShowContactModal] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const openContactModal = () => {
    setShowContactModal(true);
    setIsModalOpen(true);
  };

  const closeContactModal = () => {
    setShowContactModal(false);
    setIsModalOpen(false);
  };

  useEffect(() => {
    const body = document.body;
    let scrollBarWidth = window.innerWidth - document.documentElement.clientWidth;

    if (isModalOpen) {
      body.style.overflow = 'hidden';
      body.style.paddingRight = `${scrollBarWidth}px`; // Компенсация ширины полосы прокрутки
    } else {
      body.style.overflow = 'auto';
      body.style.paddingRight = '0px'; // Убираем компенсацию
    }

    return () => {
      body.style.overflow = 'auto';
      body.style.paddingRight = '0px';
    };
  }, [isModalOpen]);

  return (
    <div className={classes.appContainer} style={{ filter: isModalOpen ? 'brightness(0.5)' : 'brightness(1)' }}>
      <ScrollToTop />
      <Header />
      <AppRouter />
      <Footer openContactModal={openContactModal} />

      {showContactModal && (
        <>
          <ModalOverlay onClose={closeContactModal} />
          <ModalContact onClose={closeContactModal} />
        </>
      )}
    </div>
  );
}

export default App;
